import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.yZB1U4Nl.js";const b=JSON.parse('{"title":"Interface: Host","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"api/host/interfaces/Host.md","filePath":"api/host/interfaces/Host.md"}'),s={name:"api/host/interfaces/Host.md"};function n(c,e,d,l,h,i){return t(),a("div",null,[...e[0]||(e[0]=[r('<p><a href="./../../packages">@oona/vlo</a> / <a href="./../">host</a> / Host</p><h1 id="interface-host" tabindex="-1">Interface: Host <a class="header-anchor" href="#interface-host" aria-label="Permalink to &quot;Interface: Host&quot;">​</a></h1><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L93" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:93</a></p><p>A running (or startable) host: the fetch handler plus the controls a process owner needs.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="events" tabindex="-1">events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;events&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>events</strong>: <code>EventEmitter</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L111" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:111</a></p><p>In-memory side channel: <code>emit</code> (from <code>cmd.emit</code>), <code>warning</code> (dispatcher) and <code>task_scheduled</code>.</p><hr><h3 id="fetch" tabindex="-1">fetch <a class="header-anchor" href="#fetch" aria-label="Permalink to &quot;fetch&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>fetch</strong>: <a href="./../type-aliases/FetchHandler"><code>FetchHandler</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L95" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:95</a></p><p>The HTTP surface as a <code>(Request) =&gt; Response</code>. Starts the host on first call.</p><hr><h3 id="journal" tabindex="-1">journal <a class="header-anchor" href="#journal" aria-label="Permalink to &quot;journal&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>journal</strong>: <a href="./Journal"><code>Journal</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L113" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:113</a></p><p>The journal this host reads and writes.</p><hr><h3 id="publicurl" tabindex="-1">publicUrl <a class="header-anchor" href="#publicurl" aria-label="Permalink to &quot;publicUrl&quot;">​</a></h3><blockquote><p><strong>publicUrl</strong>: <code>string</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L117" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:117</a></p><p>Base URL peers reach this host on. Settable, so <a href="./../functions/serve">serve</a> can fill it after binding a port.</p><hr><h3 id="roles" tabindex="-1">roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;roles&quot;">​</a></h3><blockquote><p><code>readonly</code> <strong>roles</strong>: <code>ReadonlySet</code>&lt;<a href="./../type-aliases/Role"><code>Role</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L115" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:115</a></p><p>Roles this process holds.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="drain" tabindex="-1">drain() <a class="header-anchor" href="#drain" aria-label="Permalink to &quot;drain()&quot;">​</a></h3><blockquote><p><strong>drain</strong>(<code>options?</code>): <code>Promise</code>&lt;<a href="./DrainResult"><code>DrainResult</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L109" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:109</a></p><p>Ticks until the outbox is idle or <code>maxMs</code> (default 25 s) runs out. Concurrent callers share one drain. Rejects on a host without the <code>orchestrator</code> role.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to &quot;options?&quot;">​</a></h5><p><a href="./DrainOptions"><code>DrainOptions</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./DrainResult"><code>DrainResult</code></a>&gt;</p><hr><h3 id="start" tabindex="-1">start() <a class="header-anchor" href="#start" aria-label="Permalink to &quot;start()&quot;">​</a></h3><blockquote><p><strong>start</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L97" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:97</a></p><p>Loads the kernel, migrates the journal and starts the dispatcher. Idempotent.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="stop" tabindex="-1">stop() <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;stop()&quot;">​</a></h3><blockquote><p><strong>stop</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L102" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:102</a></p><p>Stops the dispatcher, waits up to <a href="./../variables/SHUTDOWN_GRACE_MS">SHUTDOWN_GRACE_MS</a> for in-process handlers, then closes the journal if the host opened it from a URL. Idempotent.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="tick" tabindex="-1">tick() <a class="header-anchor" href="#tick" aria-label="Permalink to &quot;tick()&quot;">​</a></h3><blockquote><p><strong>tick</strong>(): <code>Promise</code>&lt;<a href="./TickCounts"><code>TickCounts</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L104" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:104</a></p><p>One dispatcher pass. Rejects on a host without the <code>orchestrator</code> role.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Promise</code>&lt;<a href="./TickCounts"><code>TickCounts</code></a>&gt;</p>',60)])])}const u=o(s,[["render",n]]);export{b as __pageData,u as default};
